{
  "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/fork/",
  "title": "Fulu -- Fork",
  "category": "consensus-spec",
  "layer": "consensus",
  "sub_graphs": [
    {
      "id": "SG-FULU-FORK-TRIGGER",
      "name": "Fork Trigger Condition",
      "description": "Defines the condition under which the Fulu fork is activated. The fork is triggered at a specific epoch (FULU_FORK_EPOCH). The irregular state change occurs when the slot is at an epoch boundary (state.slot % SLOTS_PER_EPOCH == 0) and the current epoch equals FULU_FORK_EPOCH.",
      "invariants": [
        {
          "id": "INV-FULU-FORK-001",
          "text": "The Fulu fork upgrade MUST only occur at an epoch boundary, i.e. when state.slot % SLOTS_PER_EPOCH == 0."
        },
        {
          "id": "INV-FULU-FORK-002",
          "text": "The Fulu fork upgrade MUST only occur when compute_epoch_at_slot(state.slot) == FULU_FORK_EPOCH."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-FULU-FORK-001",
          "text": "state.slot % SLOTS_PER_EPOCH == 0"
        },
        {
          "id": "PRE-FULU-FORK-002",
          "text": "compute_epoch_at_slot(state.slot) == FULU_FORK_EPOCH"
        }
      ],
      "post_conditions": [
        {
          "id": "POST-FULU-FORK-001",
          "text": "The beacon state has been upgraded from Electra to Fulu via upgrade_to_fulu."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-FULU-FORK-001",
          "text": "An irregular state change is made: the pre-fork Electra BeaconState is transformed into a post-fork Fulu BeaconState.",
          "from_state": "electra.BeaconState",
          "to_state": "fulu.BeaconState"
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-FULU-FORK-001",
          "name": "FULU_FORK_EPOCH",
          "type": "Epoch",
          "description": "The epoch at which the Fulu fork is triggered. Configuration value (not yet definitive)."
        },
        {
          "id": "SV-FULU-FORK-002",
          "name": "SLOTS_PER_EPOCH",
          "type": "uint64",
          "description": "Number of slots per epoch, used to determine epoch boundaries."
        }
      ],
      "data_structures": [],
      "references": {
        "eips": [],
        "functions_called": [
          "compute_epoch_at_slot",
          "upgrade_to_fulu"
        ]
      }
    },
    {
      "id": "SG-FULU-UPGRADE-FUNCTION",
      "name": "upgrade_to_fulu State Upgrade Function",
      "description": "The core function that performs the Fulu fork upgrade. It takes a pre-fork Electra BeaconState and constructs a new Fulu BeaconState, copying over all existing fields and initializing new Fulu-specific fields. For pure Fulu networks, this function is applied to transition the genesis state.",
      "invariants": [
        {
          "id": "INV-FULU-UPGRADE-001",
          "text": "All fields from the pre-fork Electra BeaconState MUST be preserved in the post-fork Fulu BeaconState (except those explicitly modified or added)."
        },
        {
          "id": "INV-FULU-UPGRADE-002",
          "text": "The fork.previous_version in the post state MUST equal the fork.current_version from the pre state."
        },
        {
          "id": "INV-FULU-UPGRADE-003",
          "text": "The fork.current_version in the post state MUST equal FULU_FORK_VERSION."
        },
        {
          "id": "INV-FULU-UPGRADE-004",
          "text": "The fork.epoch in the post state MUST equal the current epoch at the time of upgrade."
        },
        {
          "id": "INV-FULU-UPGRADE-005",
          "text": "Validator set (validators, balances) MUST be identical between pre and post states."
        },
        {
          "id": "INV-FULU-UPGRADE-006",
          "text": "Finality data (justification_bits, justified checkpoints, finalized checkpoint) MUST be identical between pre and post states."
        },
        {
          "id": "INV-FULU-UPGRADE-007",
          "text": "Pending operations (pending_deposits, pending_partial_withdrawals, pending_consolidations) MUST be identical between pre and post states."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-FULU-UPGRADE-001",
          "text": "The input state (pre) MUST be a valid electra.BeaconState."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-FULU-UPGRADE-001",
          "text": "The returned state is a valid Fulu BeaconState with fork.current_version == FULU_FORK_VERSION."
        },
        {
          "id": "POST-FULU-UPGRADE-002",
          "text": "The returned state contains a newly initialized proposer_lookahead field (EIP-7917)."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-FULU-UPGRADE-001",
          "text": "The Electra BeaconState is converted into a Fulu BeaconState by constructing a new BeaconState object with all fields copied and fork version updated.",
          "from_state": "electra.BeaconState",
          "to_state": "fulu.BeaconState"
        }
      ],
      "functions": [
        {
          "id": "FN-FULU-UPGRADE-001",
          "name": "upgrade_to_fulu",
          "signature": "def upgrade_to_fulu(pre: electra.BeaconState) -> BeaconState",
          "parameters": [
            {
              "name": "pre",
              "type": "electra.BeaconState",
              "description": "The pre-fork Electra beacon state to upgrade."
            }
          ],
          "return_type": "BeaconState",
          "description": "Constructs a new Fulu BeaconState from an existing Electra BeaconState. Copies all existing fields, updates the Fork object to reflect FULU_FORK_VERSION, and initializes the new proposer_lookahead field via initialize_proposer_lookahead.",
          "calls": [
            "electra.get_current_epoch",
            "initialize_proposer_lookahead"
          ],
          "modifications": [
            "[Modified in Fulu] Fork.current_version set to FULU_FORK_VERSION",
            "[New in Fulu:EIP7917] proposer_lookahead initialized via initialize_proposer_lookahead(pre)"
          ]
        }
      ],
      "state_variables": [
        {
          "id": "SV-FULU-UPGRADE-001",
          "name": "FULU_FORK_VERSION",
          "type": "Version",
          "description": "The fork version identifier for the Fulu fork. Set as current_version in the Fork object."
        }
      ],
      "data_structures": [],
      "references": {
        "eips": [
          "EIP-7917"
        ],
        "functions_called": [
          "electra.get_current_epoch",
          "initialize_proposer_lookahead"
        ]
      }
    },
    {
      "id": "SG-FULU-FORK-OBJECT",
      "name": "Fork Version Transition",
      "description": "Defines how the Fork object within BeaconState is updated during the Fulu upgrade. The previous_version is set to the pre-fork current_version, the current_version is set to FULU_FORK_VERSION, and the epoch is set to the current epoch.",
      "invariants": [
        {
          "id": "INV-FULU-FORKOBJ-001",
          "text": "Fork.previous_version MUST equal the pre-state Fork.current_version to maintain fork chain continuity."
        },
        {
          "id": "INV-FULU-FORKOBJ-002",
          "text": "Fork.current_version MUST be set to FULU_FORK_VERSION."
        },
        {
          "id": "INV-FULU-FORKOBJ-003",
          "text": "Fork.epoch MUST equal the epoch at which the upgrade occurs."
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [
        {
          "id": "ST-FULU-FORKOBJ-001",
          "text": "Fork object transitions: previous_version=pre.fork.current_version, current_version=FULU_FORK_VERSION, epoch=current_epoch.",
          "from_state": "Fork(previous_version=*, current_version=electra_version, epoch=electra_epoch)",
          "to_state": "Fork(previous_version=electra_version, current_version=FULU_FORK_VERSION, epoch=fulu_epoch)"
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-FULU-FORK-001",
          "name": "Fork",
          "type": "Container",
          "fields": [
            {
              "name": "previous_version",
              "type": "Version",
              "description": "Set to pre.fork.current_version during upgrade."
            },
            {
              "name": "current_version",
              "type": "Version",
              "description": "Set to FULU_FORK_VERSION during upgrade."
            },
            {
              "name": "epoch",
              "type": "Epoch",
              "description": "Set to the current epoch at the time of upgrade."
            }
          ]
        }
      ],
      "references": {
        "eips": [],
        "functions_called": []
      }
    },
    {
      "id": "SG-FULU-BEACON-STATE",
      "name": "Fulu BeaconState Structure",
      "description": "The complete Fulu BeaconState structure as constructed by upgrade_to_fulu. It inherits all fields from Electra BeaconState and adds new fields introduced in the Fulu fork.",
      "invariants": [],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "functions": [],
      "state_variables": [],
