    {
      "id": "SG-FULU-EIP7917-PROPOSER-LOOKAHEAD",
      "name": "EIP-7917 Proposer Lookahead Initialization",
      "description": "Introduces the proposer_lookahead field to the Fulu BeaconState. This is a new feature from EIP-7917 that provides a pre-computed lookahead of proposer assignments. During the fork upgrade, it is initialized by calling initialize_proposer_lookahead on the pre-fork state.",
      "invariants": [
        {
          "id": "INV-FULU-EIP7917-001",
          "text": "The proposer_lookahead field MUST be initialized during the fork upgrade using initialize_proposer_lookahead(pre)."
        },
        {
          "id": "INV-FULU-EIP7917-002",
          "text": "The proposer_lookahead field MUST contain valid ValidatorIndex values for the lookahead window."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-FULU-EIP7917-001",
          "text": "A valid pre-fork Electra BeaconState must be available as input to initialize_proposer_lookahead."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-FULU-EIP7917-001",
          "text": "The proposer_lookahead field is populated with a valid sequence of proposer indices for the lookahead period."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-FULU-EIP7917-001",
          "text": "The proposer_lookahead field transitions from non-existent (in Electra state) to initialized (in Fulu state).",
          "from_state": "N/A (field does not exist in Electra)",
          "to_state": "Vector[ValidatorIndex, PROPOSER_LOOKAHEAD_EPOCHS * SLOTS_PER_EPOCH]"
        }
      ],
      "functions": [
        {
          "id": "FN-FULU-EIP7917-001",
          "name": "initialize_proposer_lookahead",
          "signature": "initialize_proposer_lookahead(pre: electra.BeaconState) -> Vector[ValidatorIndex, ...]",
          "parameters": [
            {
              "name": "pre",
              "type": "electra.BeaconState",
              "description": "The pre-fork Electra beacon state used to compute the initial proposer lookahead."
            }
          ],
          "return_type": "Vector[ValidatorIndex, PROPOSER_LOOKAHEAD_EPOCHS * SLOTS_PER_EPOCH]",
          "description": "Computes the initial proposer lookahead assignments from the pre-fork state. Referenced but not defined in this specification document.",
          "calls": [],
          "modifications": [],
          "note": "Function is referenced but defined elsewhere in the Fulu specification."
        }
      ],
      "state_variables": [
        {
          "id": "SV-FULU-EIP7917-001",
          "name": "proposer_lookahead",
          "type": "Vector[ValidatorIndex, PROPOSER_LOOKAHEAD_EPOCHS * SLOTS_PER_EPOCH]",
          "description": "[New in Fulu:EIP7917] Pre-computed proposer assignments for a lookahead window."
        },
        {
          "id": "SV-FULU-EIP7917-002",
          "name": "PROPOSER_LOOKAHEAD_EPOCHS",
          "type": "uint64",
          "description": "Configuration constant defining the number of epochs in the proposer lookahead window."
        }
      ],
      "data_structures": [],
      "references": {
        "eips": [
          "EIP-7917"
        ],
        "functions_called": [
          "initialize_proposer_lookahead"
        ]
      }
    },
    {
      "id": "SG-FULU-STATE-CONTINUITY",
      "name": "State Field Continuity Guarantees",
      "description": "Ensures that all inherited fields from the Electra BeaconState are faithfully carried over to the Fulu BeaconState during the fork upgrade. This covers genesis data, validator registry, finality state, sync committees, execution layer state, withdrawal state, and all Electra-specific pending operation queues.",
      "invariants": [
        {
          "id": "INV-FULU-CONT-001",
          "text": "genesis_time MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-002",
          "text": "genesis_validators_root MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-003",
          "text": "slot MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-004",
          "text": "latest_block_header MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-005",
          "text": "All historical data fields (block_roots, state_roots, historical_roots, historical_summaries) MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-006",
          "text": "All eth1 data fields (eth1_data, eth1_data_votes, eth1_deposit_index) MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-007",
          "text": "The validator registry (validators) and balances MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-008",
          "text": "randao_mixes and slashings MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-009",
          "text": "Epoch participation flags (previous_epoch_participation, current_epoch_participation) MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-010",
          "text": "All finality fields (justification_bits, previous_justified_checkpoint, current_justified_checkpoint, finalized_checkpoint) MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-011",
          "text": "inactivity_scores MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-012",
          "text": "Sync committee fields (current_sync_committee, next_sync_committee) MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-013",
          "text": "latest_execution_payload_header MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-014",
          "text": "Withdrawal fields (next_withdrawal_index, next_withdrawal_validator_index) MUST be unchanged across the fork."
        },
        {
          "id": "INV-FULU-CONT-015",
          "text": "All Electra-specific fields (deposit_requests_start_index, deposit_balance_to_consume, exit_balance_to_consume, earliest_exit_epoch, consolidation_balance_to_consume, earliest_consolidation_epoch, pending_deposits, pending_partial_withdrawals, pending_consolidations) MUST be unchanged across the fork."
        }
      ],
