{
  "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/p2p-interface/",
  "title": "Fulu -- Networking (P2P Interface)",
  "category": "consensus-spec",
  "layer": "consensus/networking",
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "Preset and Configuration Constants",
      "description": "Defines the preset and configuration constants introduced or modified in the Fulu fork for the P2P networking layer. Includes the KZG commitments Merkle inclusion proof depth and new data column sidecar subnet parameters (EIP-7594).",
      "invariants": [
