    {
      "id": "SG-011",
      "name": "Gossip Validation: data_column_sidecar_{subnet_id}",
      "description": "Defines the complete gossip validation rules for the data_column_sidecar_{subnet_id} topic. This is the primary data availability propagation mechanism in Fulu (PeerDAS/EIP-7594). Specifies 13 validation conditions that must pass before forwarding a DataColumnSidecar on the network, using REJECT and IGNORE semantics.",
      "invariants": [
        {
          "id": "INV-020",
          "text": "[REJECT] The sidecar MUST be valid as verified by verify_data_column_sidecar(sidecar)."
        },
        {
          "id": "INV-021",
          "text": "[REJECT] The sidecar MUST be for the correct subnet: compute_subnet_for_data_column_sidecar(sidecar.index) == subnet_id."
        },
        {
          "id": "INV-022",
          "text": "[IGNORE] The sidecar MUST NOT be from a future slot (with MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance): block_header.slot <= current_slot."
        },
        {
          "id": "INV-023",
          "text": "[IGNORE] The sidecar MUST be from a slot greater than the latest finalized slot: block_header.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)."
        },
        {
          "id": "INV-024",
          "text": "[REJECT] The proposer signature of sidecar.signed_block_header MUST be valid with respect to block_header.proposer_index pubkey."
        },
        {
          "id": "INV-025",
          "text": "[IGNORE] The sidecar's block's parent (block_header.parent_root) MUST have been seen (via gossip or non-gossip sources)."
        },
        {
          "id": "INV-026",
          "text": "[REJECT] The sidecar's block's parent (block_header.parent_root) MUST pass validation."
        },
        {
          "id": "INV-027",
          "text": "[REJECT] The sidecar MUST be from a higher slot than the sidecar's block's parent."
        },
        {
          "id": "INV-028",
          "text": "[REJECT] The current finalized_checkpoint MUST be an ancestor of the sidecar's block: get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root."
        },
        {
          "id": "INV-029",
          "text": "[REJECT] The sidecar's kzg_commitments field inclusion proof MUST be valid as verified by verify_data_column_sidecar_inclusion_proof(sidecar)."
        },
        {
          "id": "INV-030",
          "text": "[REJECT] The sidecar's column data MUST be valid as verified by verify_data_column_sidecar_kzg_proofs(sidecar)."
        },
        {
          "id": "INV-031",
          "text": "[IGNORE] The sidecar MUST be the first sidecar for the tuple (block_header.slot, block_header.proposer_index, sidecar.index) with valid header signature, sidecar inclusion proof, and KZG proof (anti-equivocation)."
        },
        {
          "id": "INV-032",
          "text": "[REJECT] The sidecar MUST be proposed by the expected proposer_index for the block's slot in the context of the current shuffling. If proposer_index cannot be immediately verified, the sidecar MAY be queued (IGNORE instead of REJECT)."
        }
      ],
      "preconditions": [
        {
          "id": "PRE-007",
          "text": "The sidecar must be a well-formed DataColumnSidecar received on a data_column_sidecar_{subnet_id} gossip topic."
        }
      ],
      "postconditions": [
        {
          "id": "POST-007",
          "text": "Only sidecars passing all REJECT and IGNORE checks are forwarded on the gossip network."
        },
        {
          "id": "POST-008",
          "text": "Clients may cache the result of the arguments tuple (sidecar.kzg_commitments, sidecar.kzg_commitments_inclusion_proof, sidecar.signed_block_header) to avoid redundant verification for sidecars of the same block."
        }
      ],
