    {
      "id": "SG-016",
      "name": "Req/Resp: DataColumnSidecarsByRange v1 Protocol",
      "description": "Defines the DataColumnSidecarsByRange v1 protocol (/eth2/beacon_chain/req/data_column_sidecars_by_range/1/) for requesting data column sidecars within a slot range and specific column indices. This is the primary mechanism for syncing missed data columns and backfilling within the MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS window. Replaces BlobSidecarsByRange for data availability sampling in Fulu.",
      "invariants": [
        {
          "id": "INV-045",
          "text": "The request MUST be encoded as an SSZ-container."
        },
        {
          "id": "INV-046",
          "text": "The response MUST consist of zero or more response_chunk, each containing a single DataColumnSidecar payload."
        },
        {
          "id": "INV-047",
          "text": "Clients MUST keep a record of data column sidecars on the epoch range data_column_serve_range = [max(current_epoch - MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, FULU_FORK_EPOCH), current_epoch] and MUST support serving requests on this range."
        },
        {
          "id": "INV-048",
          "text": "Clients MUST respond with at least the data column sidecars of the first blob-carrying block in range, if they have it, and no more than MAX_REQUEST_DATA_COLUMN_SIDECARS."
        },
        {
          "id": "INV-049",
          "text": "Clients MUST include all data column sidecars of each block from which they include data column sidecars (no partial blocks)."
        },
        {
          "id": "INV-050",
          "text": "Data column sidecars MUST be sent in (slot, column_index) order."
        },
        {
          "id": "INV-051",
          "text": "Slots without known data columns MUST be skipped."
        },
        {
          "id": "INV-052",
          "text": "The response MUST contain no more than count * NUMBER_OF_COLUMNS data column sidecars."
        },
        {
          "id": "INV-053",
          "text": "Clients MUST respond with data columns from their view of the current fork choice (single chain defined by current head)."
        },
        {
          "id": "INV-054",
          "text": "Clients MUST respond with data column sidecars that are consistent from a single chain within the context of the request."
        },
        {
          "id": "INV-055",
          "text": "Blocks from slots before finalization MUST lead to the finalized block reported in the Status handshake."
        },
        {
          "id": "INV-056",
          "text": "Nodes that bootstrap from a weak subjectivity checkpoint MUST backfill the local data columns database to at least data_column_serve_range."
        }
      ],
      "preconditions": [
        {
          "id": "PRE-010",
          "text": "Before consuming each response chunk, the reader SHOULD verify the sidecar via verify_data_column_sidecar, verify_data_column_sidecar_inclusion_proof, and verify_data_column_sidecar_kzg_proofs."
        }
      ],
      "postconditions": [
        {
          "id": "POST-010",
          "text": "After the initial data column sidecar, clients MAY stop responding if their fork choice changes."
        }
      ],
